C9 = [
("s3","Waarom stel je een versterkend element in?","Zodat het een zo groot mogelijk signaal met zo min mogelijk vervorming kan verwerken."),
("s3","Hoe krijg je alle gelijkspanningen en -stromen meestal geregeld?","Met één voedingsspanning en een goed ontworpen schakeling: onderlinge afstemming van spanningen en stromen."),
("s3","Hoe moet bij een N-FET de source ten opzichte van de gate zijn?","Een beetje positief (de gate is dus negatief ten opzichte van de source). Bij een P-FET andersom."),
("s3","Hoe moet bij een NPN-transistor de basis ten opzichte van de emitter zijn?","Een beetje positief, zodat de basis-emitterovergang geleidt. Bij PNP andersom."),
("s4","Wat is een belastingslijn?","Een lijn in de karakteristiek met alle theoretisch mogelijke combinaties van spanning over het element en over de weerstand in serie, samen gelijk aan de voedingsspanning."),
("s4","Waarop is de belastingslijn gebaseerd?","Op de tweede wet van Kirchhoff: de bronspanning is de som van de spanningen over element en weerstand."),
("s4","Wat is het werkpunt?","Het snijpunt van de belastingslijn met de karakteristiek (bij een FET met de karakteristiek van de gekozen U_GS). Het geeft de spanningsverdeling en de stroom."),
("s4","Wat geeft punt A van de belastingslijn van een FET aan?","U_DS = 0 V: de hele voedingsspanning staat over R_D + R_S. De stroom is dan U/(R_D+R_S)."),
("s4","Wat geeft punt B van de belastingslijn aan?","I_D = 0: de FET is stroomloos en de volle voedingsspanning staat over de FET."),
("s4","Hoe bepaal je R_D + R_S uit de belastingslijn?","Voedingsspanning gedeeld door de stroom bij U_DS = 0 (punt A). Bijvoorbeeld 25 V / 20 mA = 1250 Ω."),
("s4","Waar kies je normaal het werkpunt?","Ongeveer in het midden van het bruikbare deel van de belastingslijn, zodat U_DS evenveel omhoog als omlaag kan."),
("s4","Waarom is niet de hele belastingslijn bruikbaar?","Links van de kniepunten lopen de karakteristieken steil op. Een werkpunt daar geeft flinke vervorming. Het bruikbare deel begint bij punt A′."),
("s4","Hoe bepaal je R_S uit het werkpunt?","R_S = −U_GS / I_D. Voorbeeld: 3 V / 8 mA = 375 Ω."),
("s4","Hoe bepaal je R_D uit het werkpunt?","R_D = (U_voeding − U_DS − U_RS) / I_D. De drainstroom is gelijk aan de sourcestroom."),
("s4","Waarom is de drainstroom gelijk aan de sourcestroom?","Volgens de eerste wet van Kirchhoff: wat de FET ingaat, gaat er ook weer uit."),
("s4","Formule voor de spanningsversterking met sourceweerstand?","Au = R_D / (R_S + 1/S)."),
("s4","Wat gebeurt er met Au als je R_S ontkoppelt met een condensator?","De invloed van R_S valt weg: Au = R_D / (1/S) = S · R_D. De versterking wordt veel groter (bijvoorbeeld van 1,6 naar 4)."),
("s4","Waarom moet C_S voor het te versterken gebied een verwaarloosbare reactantie hebben?","Anders werkt R_S nog mee voor wisselspanning en blijft de versterking lager."),
("s4","Waarvoor dient een condensator parallel aan de emitterweerstand?","Om de emitterweerstand voor wisselspanning te ontkoppelen, zodat de signaalversterking groter wordt."),
("s4","Wat bepaalt het werkpunt bij gelijkspanning, wat bij wisselspanning?","Gelijkstroom: R_D + R_S. Met ontkoppeld R_S telt voor wisselstroom alleen R_D: de wisselstroombelastingslijn wordt steiler."),
("s4","Gelden belastingslijnen ook voor buis en transistor?","Ja, op dezelfde manier. Bij een transistor moet β zo groot zijn dat de basisstroom verwaarloosbaar is ten opzichte van collector- en emitterstroom."),
("s4","Een Si-transistor met β = 20, R_b = 47 kΩ aan 12,5 V en R_c = 1,2 kΩ. Hoe bereken je de collectorspanning?","I_b = (12,5 − 0,6) V / 47 kΩ ≈ 0,25 mA; I_c = β·I_b = 5 mA; U over R_c = 6 V; de collectorspanning is 12,5 − 6 = 6,5 V."),
("s6","Wat is de dissipatie van een FET?","P = I_D · U_DS."),
("s6","Wat is een dissipatiehyperbool?","De grafiek van I_D = P / U_DS bij vaste P: alle combinaties van stroom en spanning met dezelfde dissipatie."),
("s6","Wat gebeurt er als de dissipatie boven het maximum komt?","Het element wordt te heet en gaat stuk."),
("s6","Waar vind je de maximale waarden van een element?","In het databalad: maximale U_DS, I_D en dissipatie (op het examen niet)."),
("s6","Waarom combineer je een belastingslijn met dissipatiehyperbolen?","Om te controleren of het werkpunt en de hele lijn binnen de toegestane dissipatie blijven."),
("s6","Wat zijn de ‘verboden gebieden’ in de karakteristiek?","Gebieden voorbij de maximale spanning, de maximale stroom en de dissipatiehyperbool."),
("s8","Waarom schakel je versterkertrappen achter elkaar?","Eén trap geeft meestal niet genoeg versterking."),
("s8","Welke drie koppelmethoden zijn er?","Weerstandskoppeling, smoorspoelkoppeling en transformatorkoppeling."),
("s9","Wat zijn bij weerstandskoppeling de echte koppelelementen?","De koppelcondensatoren (C_k). De drain- of collectorweerstanden zetten stroom om in spanning."),
("s9","Waarvan hangt de capaciteit van een koppelcondensator af?","Van de laagste te versterken frequentie en de weerstand in het koppelcircuit (samen een RC-filter)."),
("s9","Wat vormen koppelcondensator en gateweerstand samen?","Een hoogdoorlaatfilter. De kantelfrequentie moet onder de laagste te versterken frequentie liggen."),
("s9","Welke koppelcondensatoren zie je bij FET en buis in LF-versterkers?","Ongeveer 10–100 nF, meestal geen elco."),
("s9","Waarom zijn koppelcondensatoren bij transistoren groter dan bij FET’s?","De ingangsweerstand van een transistortrap is veel lager. Ze zijn ongeveer 1–10 µF, meestal elco’s."),
("s9","Hoe is de ingangsweerstand van een transistortrap met spanningsdeler?","De parallelschakeling van R1, R2 en (h_FE · R_e): 1/Zin ≈ 1/R1 + 1/R2 + 1/(β·R_e)."),
("s9","Hoe groot zijn ontkoppelcondensatoren in het source- of emittercircuit ongeveer?","Ongeveer 100 µF of meer (enkele honderden µF bij transistoren), vrijwel altijd elco’s."),
("s9","Waarom zie je bij FET en buis zelden elco’s als koppelcondensator?","De ingangsimpedantie van gate en rooster is hoog, dus een kleine capaciteit volstaat. Transistoren hebben een lage ingangsimpedantie op de basis."),
("s9","Welk frequentiegebied heeft een goede audioversterker?","Ongeveer 10 Hz tot 20 kHz. Voor spraak is 300 Hz tot 3 kHz voldoende."),
("s9","Wat is een frequentie-lineaire LF-versterker?","Een versterker die alle frequenties tussen f1 en f2 even sterk versterkt (vlakke karakteristiek)."),
("s9","Wordt weerstandskoppeling in HF-versterkers toegepast?","Nauwelijks. Voor HF gebruikt men koppeling via LC-kringen die een klein frequentiegebied doorlaten."),
("s9","Wat gebeurt er met de bandbreedte als je twee gelijke versterkers achter elkaar schakelt?","De totale bandbreedte wordt iets kleiner."),
("s9","Welke koppeling hoort bij LF-versterkers?","Weerstandskoppeling: de versterking is voor alle frequenties in het audiogebied (bij benadering) gelijk."),
("s10","Wat is smoorspoelkoppeling?","De drain-, collector- of anodeweerstand is vervangen door een smoorspoel; het signaal gaat via een koppelcondensator naar de volgende trap."),
("s10","Welk voordeel heeft een smoorspoel als belasting?","In theorie dissipeert hij geen vermogen. De gelijkspanning op de drain is vrijwel de voedingsspanning."),
("s10","Waarom kan met smoorspoelkoppeling een hogere versterking worden bereikt?","Hogere spanning op de drain (lage gelijkstroomweerstand) en de uitgangsspanning kan in theorie uitslingeren tot twee keer de voedingsspanning."),
("s10","Waar wordt smoorspoelkoppeling toegepast?","In HF-schakelingen met een klein frequentiegebied. In LF niet meer."),
("s10","Waarom niet smoorspoelkoppeling in LF-versterkers?","Er is een grote, lompe, dure spoel nodig, en de reactantie neemt toe met de frequentie, dus de versterking is frequentie-afhankelijk."),
("s11","Wat is transformatorkoppeling?","De primaire van een transformator staat in de uitgangskring van de ene trap; de secundaire voert het signaal naar de ingang van de volgende."),
("s11","Waar wordt transformatorkoppeling toegepast?","In HF-versterkers (algemeen) en in LF-eindtrappen voor groot vermogen. Voor LF-voorversterkers niet meer."),
("s11","Wat is een koppeltransformator met afgestemde kring?","Een transformator waarvan één of alle wikkelingen met een condensator een afgestemde kring vormen: inductief gekoppelde afgestemde kringen. Gebruikelijk in ontvangers."),
("s11","Wat doet de tweede gate van een dual-gate MOSFET in een HF-trap?","Dezelfde taak als het schermrooster van een penthode: de capaciteit tussen gate 1 en drain minimaal maken, zodat de koppeling tussen de drainkring en de ingangskring zo klein mogelijk is."),
("s14","Waarom is klasse A geen efficiënte instelling?","Er loopt altijd gelijkstroom, ook zonder signaal. Die gaat volledig op in warmte."),
("s14","Welke klassen van instelling zijn er?","A, B, C en AB."),
("s14","Waarom bestaan er klassen van instelling?","Om het rendement van grote-vermogenversterkers (zenders) te verhogen: minder gelijkstroomdissipatie."),
("s15","Hoe is een element in klasse A ingesteld?","In het midden van het lineaire deel van de steilheidsgrafiek. Het geleidt altijd, voor de volle sinus."),
("s15","Wat zijn de kenmerken van klasse A?","Gelijkstroom blijft met en zonder signaal vrijwel gelijk; HF en LF; weinig vervorming; vermogensrendement hooguit 25%."),
("s15","Wat is het hoogst haalbare vermogensrendement in klasse A?","Ongeveer 25%. Theoretisch 33% bij volledige uitsturing met een DC-deel gelijk aan de amplitude."),
("s15","Wanneer ontstaan harmonischen in een klasse A LF-versterker?","Bij te grote uitsturing (overbelasting): het signaal komt in het niet-lineaire gebied."),
("s15","Wat zijn de polariteiten van een NPN-transistor in klasse A?","Collector positief ten opzichte van de emitter, basis een beetje positief ten opzichte van de emitter. Bij PNP is het omgekeerd."),
("s15","Hoe zijn de roosters van een penthode in klasse A ingesteld?","Stuurrooster negatief, schermrooster positief ten opzichte van de kathode; remrooster is met de kathode verbonden (niet positief)."),
("s16","Hoe is een element in klasse B ingesteld?","Precies in het afknijppunt: zonder signaal loopt er (bijna) geen stroom, met signaal alleen tijdens één halve sinus."),
("s16","Welk rendement haalt klasse B?","Rond de 50%."),
("s16","Hoe voorkom je vervorming in klasse B?","Met een balansversterker (twee elementen, elk één helft) of met afgestemde filters die de harmonischen wegfilteren."),
("s16","Wat is een balansversterker (push-pull)?","Twee versterkende elementen in klasse B; het ene versterkt de positieve en het andere de negatieve halve sinus. Ze worden met transformatoren met middenaftakking gekoppeld."),
("s16","Waarom moeten de twee elementen van een balansversterker goed gelijk zijn?","Anders zijn de twee helften niet even groot en ontstaat vervorming. Er bestaan gematchte paren."),
("s16","Wat is crossoververvorming?","Vervorming bij de nuldoorgang van het signaal, doordat beide elementen sperren of het begin van de steilheidskarakteristiek niet lineair is."),
("s16","Hoe stel je een FET of buis in klasse B in?","Met een negatieve gate- of roosterspanning die precies het afknijppunt bereikt, via een smoorspoel toegevoerd."),
("s16","Hoe stel je een transistor in klasse B in?","Een in doorlaatrichting geschakelde diode (Si of Ge) levert een basisspanning waarbij net geen stroom loopt."),
("s17","Hoe is een element in klasse C ingesteld?","Voorbij het afknijppunt: bij FET en buis een nog negatievere gate- of roosterspanning dan in klasse B; bij een transistor de basis via leiding of weerstand aan 0 V."),
("s17","Wat versterkt klasse C?","Alleen het bovenste deel van een halve sinusperiode. Er loopt maar kort stroom."),
("s17","Wat is het nadeel van klasse C?","Veel vervorming; kleine signalen komen niet door. Niet evenveel versterking voor alle amplituden."),
("s17","Welke signalen zijn geschikt voor klasse C?","Alleen signalen waarbij die vervorming de informatie niet aantast (bijvoorbeeld FM, CW)."),
("s17","Welke instelling heeft het hoogste rendement?","Klasse C: het hoogste rendement, maar ook de meeste vervorming en dus de meeste harmonischen."),
("s17","Bij welke klasse is de kans op harmonischen het grootst?","Klasse C."),
("s17","Bij welke klasse is de kans op harmonischen het kleinst?","Klasse A."),
("s17","Waarom staat een transistor met basis op 0 V in klasse C?","De basis-emitterdiode heeft ongeveer 0,6 V (Si) of 0,2 V (Ge) nodig om te geleiden; daaronder loopt geen stroom."),
("s17","Hoe kan een schakeling zichzelf in klasse C trekken?","Door gelijkrichting van een deel van het signaal: de koppelcondensator laadt op en de basis-, gate- of roosterspanning wordt negatiever, met een weerstand naar massa."),
("s17","Waarvoor is vervorming door klasse C gewenst?","Voor frequentievermenigvuldiging: de vervorming maakt harmonischen; een kring afgestemd op de gewenste harmonische filtert die eruit."),
("s17","Wat gebeurt er in een frequentieverdrievoudiger met een transistor in klasse C?","In de collectorstroom zitten de grondfrequentie f en de harmonische 3f (en andere); de afgestemde kring selecteert 3f."),
("s17","Welk element is het meest geschikt voor frequentievermenigvuldiging?","Een versterker in klasse C."),
("s17","Welke trap volgt meestal op een klasse C-vermenigvuldiger?","Een kring afgestemd op de gewenste harmonische, daarna vaak een klasse A-trap."),
("s17","Waarvoor gebruik je klasse C in zenders?","Voor eindtrappen en vermenigvuldigers waar groot rendement nodig is en de vervorming de informatie niet aantast."),
("s18","Wat is klasse AB?","Het midden tussen A en B: er loopt zonder signaal een kleine stroom. Voor kleine signalen klasse A, voor grote bijna klasse B."),
("s18","Hoe is het rendement van klasse AB?","Tussen dat van A en B in; meer naar A is lager rendement, meer naar B hoger rendement maar meer vervorming."),
("s18","Waarom is klasse AB bij transistoren moeilijk in te stellen?","De emitter-basisdiode is steil, vooral bij een zeer kleine emitterweerstand."),
("s18","Waarom heeft een transistor een emitterweerstand nodig?","Om het gedrag van de transistor in de hand te houden bij opwarming: een warme halfgeleider trekt meer stroom."),
]

